# Exportación conservadora: sin inventar campos bibliográficos faltantes.
def esc(s):return str(s).replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
bib=[]
for r in rows+extra_rows:
 fields={'title':r[2],'author':r[1].replace(';',' and '),'year':r[3],'url':r[6],'note':r[7]+'; acceso 2026-10-20; '+r[8]}
 if r[5]:fields['doi']=r[5]
 bib.append('@misc{'+r[0]+',\n'+',\n'.join('  '+k+' = {'+esc(v)+'}' for k,v in fields.items())+'\n}')
(P/'revision/referencias.bib').write_text('\n\n'.join(bib),encoding='utf-8')
# Cribado individual de los40 resultados exportados desde Crossref.
eligible={'10.1109/indiscon66021.2025.11252350','10.1016/s1296-2074(01)01116-5','10.32604/csse.2023.025293','10.1108/14684520710747220','10.1007/978-3-031-57675-1_5','10.1016/j.culher.2017.12.012','10.11591/ijeecs.v35.i1.pp583-592'}
screen=[];seen={};raw=[]
for p in sorted((P/'revision').glob('crossref_[1-4].json')):
 for i,x in enumerate(json.loads(p.read_text())['message']['items'],1):
  rid=f'C{p.stem[-1]}-{i:02}';title=' '.join(x.get('title',[]));doi=x['DOI'].lower();key=re.sub(r'\W+','',title.lower());dup=seen.get(key);seen[key]=rid
  row={'id':rid,'origen':p.name,'titulo':title,'doi':doi,'url':x.get('URL',''),'lectura':'titulo de metadatos Crossref'}
  if dup:row.update(decision='DUPLICADO',razon='Mismo título; versión en otra plataforma; conservar '+dup)
  elif doi=='10.32604/csse.2023.025293':row.update(decision='INCLUIDO_EVALUACION_TEXTO',razon='Recuperado después del intento DOI; método y resultados HTML evaluados',lectura='texto completo, secciones3–5')
  elif doi in eligible:row.update(decision='PENDIENTE_TEXTO_COMPLETO',razon='Pertinente por título/resumen; intento de acceso sin texto evaluable completo')
  else:
   reason='Tema patrimonial/textil sin método de recuperación o representación transferible identificado en título/resumen'
   if title in ['CONCLUSION:','GLOSSARY','INDEX','REFERENCES','NOTES','PREFACE','ACKNOWLEDGMENTS']:reason='Sección editorial de libro, no estudio autónomo'
   if 'Damage-Aware' in title:reason='Restauración/generación de imágenes, fuera del núcleo de recuperación; preprint sin validación examinada'
   if 'Hypergraph matching' in title:reason='Emparejamiento genérico; sin aplicación patrimonial o representación de recuperación identificada'
   row.update(decision='EXCLUIDO_TITULO_RESUMEN',razon=reason)
  screen.append(row);raw.append(x)
for r in rows:
 screen.append({'id':r[0],'origen':'búsqueda web dirigida/referencias del PDF','titulo':r[2],'doi':r[5],'url':r[6],'lectura':r[8],'decision':'INCLUIDO_EVALUACION_TEXTO' if r[0] in ['S03','S05','S06'] else 'CONTEXTO_PARCIAL','razon':'Método/datos/evaluación leídos' if r[0] in ['S03','S05','S06'] else 'Útil al mapeo; no se declara evaluación integral del texto'})
with (P/'revision/cribado_registros.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=screen[0]);w.writeheader();w.writerows(screen)
from collections import Counter
counts=Counter(r['decision'] for r in screen)
(P/'revision/conteos_prisma.json').write_text(json.dumps({'registros_importados':len(screen),'crossref':40,'seleccion_web_dirigida':24,'decisiones':dict(counts),'nota':'Los 21 contextos parciales no se cuentan como estudios con texto completo evaluado; S04 yS05 son dos informes de una familia'},indent=2,ensure_ascii=False))
